const payload = $input.first()?.json ?? {};
const jobs = Array.isArray(payload.jobs) ? payload.jobs : [];
const state = $getWorkflowStaticData('global');
state.seenJobs ??= {};
const rolePattern = /automation|n8n|workflow|rpa|zapier|make\.com/i;
const now = Date.now();

for (const [id, seenAt] of Object.entries(state.seenJobs)) {
  if (now - Date.parse(seenAt) > 45 * 24 * 60 * 60 * 1000) delete state.seenJobs[id];
}

const matches = [];
for (const job of jobs) {
  const roleText = [job.title, job.category, ...(job.tags ?? [])].join(' ');
  if (job.job_type !== 'part_time' || !rolePattern.test(roleText) || state.seenJobs[job.id]) continue;
  state.seenJobs[job.id] = new Date(now).toISOString();
  const company = job.company_name || 'the hiring team';
  matches.push({
    json: {
      jobId: job.id,
      title: job.title,
      company,
      jobType: job.job_type,
      location: job.candidate_required_location,
      salary: job.salary || 'Not listed',
      postedAt: job.publication_date,
      source: 'Remotive',
      applicationUrl: job.url,
      status: 'Needs your review',
      applicationNoteDraft: `Hello ${company} hiring team,\n\nI am interested in the part-time ${job.title} role. My relevant experience includes [add accurate examples from your background]. I am particularly interested in [mention a specific responsibility from the listing].\n\nThank you for your consideration,\n[Your name]`,
      reviewBeforeApplying: true
    }
  });
}

return matches;
